export function updateOrder(state,index,patch){const old=state?.orders?.[index];if(!old||!patch||typeof patch!=='object')return false;const amount=patch.amount===undefined?+old.amount:+patch.amount,status=String(patch.status??old.status),date=String(patch.date??old.date),method=String(patch.paymentMethod??old.paymentMethod??'');if(!Number.isFinite(amount)||amount<0||!ORDER_STATUSES.includes(status)||!date||method&&!PAYMENT_METHODS.includes(method)||!orderTransitionAllowed(String(old.status||'open'),status))return false;const next={...old,...patch,amount,status,date,paymentMethod:method};if(old.status==='paid')financeDelta(state,old.date,-(+old.amount||0),0);state.orders[index]=next;if(next.status==='paid')financeDelta(state,next.date,next.amount,0);return true}
