export function recordInvoice(state,{supplier,reference,date,dueDate,amount,status='pending'}){const vendor=String(supplier||'').trim(),ref=String(reference||'').trim(),day=String(date||localDate()),supplierDays=state?.suppliers?.find(x=>String(x.name||'').trim().toLocaleLowerCase()===vendor.toLocaleLowerCase())?.paymentDays,autoDue=()=>{const d=new Date(day+'T12:00:00');if(Number.isNaN(d.getTime()))return day;d.setDate(d.getDate()+(Number.isInteger(+supplierDays)?+supplierDays:30));return localDate(d)},due=String(dueDate||autoDue()),value=+amount,currentStatus=String(status||'pending');if(!vendor||!ref||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(day)||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(due)||due<day||!Number.isFinite(value)||value<0||!['pending','paid'].includes(currentStatus))return false;if((state.invoices||[]).some(x=>String(x.supplier||'').trim().toLocaleLowerCase()===vendor.toLocaleLowerCase()&&String(x.reference||'').trim().toLocaleLowerCase()===ref.toLocaleLowerCase()&&x.date===day))return false;const entry={supplier:vendor,reference:ref,date:day,dueDate:due,amount:value,status:currentStatus};state.invoices.unshift(entry);return entry}
export function markInvoicePaid(state,index,now=new Date()){const invoice=state?.invoices?.[index];if(!invoice||!Number.isInteger(index)||index<0||invoice.status==='paid')return false;invoice.status='paid';invoice.paidAt=now.toISOString();return invoice}
export function integrateInvoiceReceipt(state,{supplier,reference,date,items}){const vendor=String(supplier||'').trim(),ref=String(reference||'').trim(),day=String(date||localDate()),lines=Array.isArray(items)?items.map(x=>({name:String(x?.name||'').trim(),quantity:+x?.quantity,unit:String(x?.unit||'').trim(),unitPrice:+x?.unitPrice})):[];if(!vendor||!ref||!lines.length||lines.some(x=>!x.name||!Number.isFinite(x.quantity)||x.quantity<=0||!Number.isFinite(x.unitPrice)||x.unitPrice<0))return false;if((state.invoices||[]).some(x=>String(x.supplier||'').trim().toLocaleLowerCase()===vendor.toLocaleLowerCase()&&String(x.reference||'').trim().toLocaleLowerCase()===ref.toLocaleLowerCase()&&x.date===day))return false;const total=lines.reduce((sum,x)=>sum+x.quantity*x.unitPrice,0),invoice=recordInvoice(state,{supplier:vendor,reference:ref,date:day,amount:total,status:'pending'});if(!invoice)return false;if(!(state.suppliers||[]).some(x=>String(x.name||'').trim().toLocaleLowerCase()===vendor.toLocaleLowerCase()))recordRegistry(state,'suppliers',{name:vendor,contact:''});for(const line of lines){let item=state.stock.find(x=>String(x.name||'').trim().toLocaleLowerCase()===line.name.toLocaleLowerCase()),previousPrice=item?(+item.price||0):0;if(!item){item={id:newStockId(),name:line.name,unit:line.unit,qty:0,price:line.unitPrice,min:0,reorderTarget:0,preferredSupplier:vendor,source:'invoice-photo'};state.stock.unshift(item)}else{if(line.unit&&!item.unit)item.unit=line.unit;item.price=line.unitPrice;if(!String(item.preferredSupplier||'').trim())item.preferredSupplier=vendor}state.priceHistory=Array.isArray(state.priceHistory)?state.priceHistory:[];state.priceHistory.unshift({stockId:item.id,product:item.name,supplier:vendor,unit:line.unit||item.unit||'',previousPrice,unitPrice:line.unitPrice,date:day,reference:ref,recordedAt:new Date().toISOString()});if(state.priceHistory.length>4000)state.priceHistory.length=4000;if(!recordDelivery(state,{supplier:vendor,stockId:item.id,qty:line.quantity,date:day,temperature:'',lot:ref,status:'accepted'}))return false}recordPurchase(state,{supplier:vendor,date:day,amount:total,note:ref});return{invoice,total,items:lines}}
export function recordPurchase(state,{supplier,date,amount,note}){const value=+amount;if(!Number.isFinite(value)||value<0)return false;const entry={supplier:String(supplier||''),date:date||localDate(),amount:value,note:String(note||'')};state.purchases.unshift(entry);financeDelta(state,entry.date,0,entry.amount);return entry}
export function updatePurchase(state,index,patch){const old=state?.purchases?.[index];if(!old||!patch||typeof patch!=='object')return false;const amount=patch.amount===undefined?+old.amount:+patch.amount,date=patch.date??old.date;if(!Number.isFinite(amount)||amount<0||!date)return false;const next={...old,...patch,amount,date};financeDelta(state,old.date,0,-(+old.amount||0));state.purchases[index]=next;financeDelta(state,next.date,0,next.amount);return true}
export function removePurchase(state,index){const old=state?.purchases?.[index];if(!old)return false;financeDelta(state,old.date,0,-(+old.amount||0));state.purchases.splice(index,1);return true}
export function syncFinanceSnapshot(state){const latest=state.financeHistory?.[0]||{revenue:0,covers:0,expenses:0};state.revenue=+latest.revenue||0;state.covers=+latest.covers||0;state.expenses=+latest.expenses||0;return latest}
export function recordFinance(state,{date,revenue,covers,expenses}){const x=ensureFinanceDay(state,date);x.manualRevenue=Math.max(0,+revenue||0);x.manualExpenses=Math.max(0,+expenses||0);x.covers=Math.max(0,+covers||0);x.payments=normalizePayments({});recomputeFinanceRow(x);state.financeHistory.sort((a,b)=>b.date.localeCompare(a.date));syncFinanceSnapshot(state);return x}
export function recordDetailedFinance(state,{date,covers,payments}){if(!state||!Array.isArray(state.financeHistory))return false;const day=String(date||localDate());if(!/^\d{4}-\d{2}-\d{2}$/.test(day))return false;const normalized=normalizePayments(payments),x=ensureFinanceDay(state,day),entered=paymentTotal(normalized);x.payments=normalized;x.manualRevenue=Math.max(0,entered-(+x.orderRevenue||0));x.covers=Math.max(0,+covers||0);recomputeFinanceRow(x);state.financeHistory.sort((a,b)=>b.date.localeCompare(a.date));syncFinanceSnapshot(state);return x}
export function recordExpenseEntry(state,{date,category,amount,method,note=''}){if(!state||!Array.isArray(state.expenseEntries))return false;const day=String(date||localDate()),value=+amount,cat=String(category||''),pay=String(method||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||!EXPENSE_CATEGORIES.includes(cat)||!PAYMENT_METHODS.includes(pay)||!Number.isFinite(value)||value<0)return false;const entry={date:day,category:cat,amount:value,method:pay,note:String(note||'')};state.expenseEntries.unshift(entry);const x=ensureFinanceDay(state,day);x.expenseEntryExpenses=(+x.expenseEntryExpenses||0)+value;recomputeFinanceRow(x);state.financeHistory.sort((a,b)=>b.date.localeCompare(a.date));syncFinanceSnapshot(state);return entry}
export function removeExpenseEntry(state,index){const entry=state?.expenseEntries?.[index];if(!entry||!Number.isInteger(index)||index<0)return false;state.expenseEntries.splice(index,1);const x=state.financeHistory?.find(row=>row.date===entry.date);if(x){x.expenseEntryExpenses=Math.max(0,(+x.expenseEntryExpenses||0)-(+entry.amount||0));recomputeFinanceRow(x);if(!x.revenue&&!x.expenses&&!x.covers)state.financeHistory.splice(state.financeHistory.indexOf(x),1)}syncFinanceSnapshot(state);return true}
export function financeTotals(state,period='day',now=new Date()){const start=new Date(now);start.setHours(0,0,0,0);if(period==='month')start.setDate(1);else if(period==='week')start.setDate(start.getDate()-(start.getDay()+6)%7);const rows=state.financeHistory.filter(x=>{const d=new Date(`${x.date}T00:00:00`);return d>=start&&d<=now});return rows.reduce((a,x)=>(a.revenue+=+x.revenue||0,a.covers+=+x.covers||0,a.expenses+=+x.expenses||0,a),{revenue:0,covers:0,expenses:0,rows})}
export function financeDayTotals(state,date=localDate()){const selected=/^\d{4}-\d{2}-\d{2}$/.test(date||'')?date:localDate();return financeTotals(state,'day',new Date(`${selected}T23:59:59.999`))}
export function revenueSeries(state,period='day',now=new Date()){const count=period==='month'?6:7,anchor=new Date(now.getFullYear(),now.getMonth(),now.getDate());if(period==='week')anchor.setDate(anchor.getDate()-(anchor.getDay()+6)%7);if(period==='month')anchor.setDate(1);const points=Array.from({length:count},(_,index)=>{const date=new Date(anchor);if(period==='month')date.setMonth(date.getMonth()-(count-1-index));else date.setDate(date.getDate()-(count-1-index)*(period==='week'?7:1));return{key:localDate(date),date,revenue:0}}),byKey=new Map(points.map(point=>[point.key,point]));for(const row of state.financeHistory||[]){if(!/^\d{4}-\d{2}-\d{2}$/.test(row.date||''))continue;const date=new Date(`${row.date}T12:00:00`);if(Number.isNaN(date.getTime())||localDate(date)!==row.date||row.date>localDate(now))continue;if(period==='week')date.setDate(date.getDate()-(date.getDay()+6)%7);if(period==='month')date.setDate(1);const point=byKey.get(localDate(date));if(point)point.revenue+=+row.revenue||0}return points}
